/* 组件就绪后执行 */
Eam.registerInit(async function(){
/* 保养计划列表，全部数据通过异步接口。 */
await (async()=>{if(!document.getElementById('pm-rows'))return;const $=id=>document.getElementById(id),api=EamMaintenanceApi,status={draft:'草稿',pending_review:'待审核',published:'已发布',paused:'已暂停',terminated:'已终止'},unit={day:'日',week:'周',month:'月'};let page=1,ticket=0,config,hiddenColumns=[];const query=new URLSearchParams(location.search);let selectedEquipment=query.get('equipment')||'';for(const [id,key,label]of [['pm-import','import','导入（本批未启用）'],['pm-export','export','导出权限范围计划'],['pm-columns','columns','列设置'],['pm-refresh','refresh','刷新']])EamUiComponents.toolIcon($(id),key,label);EamUiComponents.toolIcon(document.querySelector('[data-filter-toggle]'),'filter','高级筛选');
function params(p=page,size=8){return new URLSearchParams({equipmentId:$('pm-equipment').value||selectedEquipment,status:$('pm-status').value,unit:$('pm-unit').value,keyword:$('pm-search').value,page:p,pageSize:size});}
async function load(){const request=++ticket;EamUiComponents.setTableStatus('pm-rows','loading');$('pm-refresh').disabled=true;try{const data=await api.request('GET','/maintenance/plans?'+params());if(request!==ticket)return;if(page>1&&data.total<=(page-1)*8){page=1;return load();}$('pm-rows').replaceChildren();for(const p of data.items){const tr=document.createElement('tr');const values=[p.name+'\n'+p.code,config.equipment.find(e=>e.id===p.equipmentId)?.name||p.equipmentId,p.interval===1?({day:'每日',week:'每周',month:'每月'}[p.unit]):'每'+p.interval+({day:'天',week:'周',month:'个月'}[p.unit]),p.bindings.map(b=>(b.type==='person'?config.people:config.positions).find(x=>x.id===b.id)?.name||b.id).join('、'),p.assignmentMode==='dispatch'?'主管派工':config.people.find(x=>x.id===p.primaryPersonId)?.name,'V'+p.planVersion+' · '+status[p.status],p.nextWindow];for(const [i,v]of values.entries()){const td=document.createElement('td');if(i===0){const name=document.createElement('strong'),code=document.createElement('small');name.textContent=p.name;code.textContent=p.code;td.append(name,code);}else if(i===5){const tag=document.createElement('span'),version=document.createElement('small');tag.className='badge '+(p.status==='published'?'text-bg-success':'text-bg-secondary');tag.textContent=status[p.status];version.textContent='V'+p.planVersion+(p.activeVersion&&p.activeVersion!==p.planVersion?' / 有效V'+p.activeVersion+' '+status[p.activeStatus||'published']:'');td.append(tag,version);}else{const span=document.createElement('span');span.textContent=v;td.append(span);}td.title=v;tr.append(td);}const td=document.createElement('td');const button=document.createElement('button');button.className='btn btn-sm btn-outline-primary';button.textContent=p.actions.edit?'编辑':p.actions.approve?'审核':'详情';button.onclick=()=>Eam.go('maintenance-plan',{id:p.id,equipment:p.equipmentId});td.append(button);tr.append(td);$('pm-rows').append(tr);}$('pm-create').disabled=!data.canCreate;EamUiComponents.decorateTables();EamUiComponents.columnVisibility($('pm-rows').closest('table'),hiddenColumns);EamUiComponents.setTableStatus('pm-rows','loaded');$('pm-load').textContent='已读取 · 当前页'+data.items.length+'条';EamUiComponents.pagination($('pm-pagination'),{page,pages:Math.max(1,Math.ceil(data.total/8)),total:data.total,pageSize:8,onChange:n=>{page=n;load();}});}catch(error){$('pm-load').textContent=error.message;EamUiComponents.setTableStatus('pm-rows',error.code==='LOADING'?'loading':'error',error.message,load);}finally{if(request===ticket)$('pm-refresh').disabled=false;}}
$('pm-refresh').onclick=load;$('pm-create').onclick=()=>Eam.go('maintenance-plan',{create:'1',equipment:$('pm-equipment').value||selectedEquipment});for(const id of ['pm-search','pm-status','pm-equipment','pm-unit'])$(id).addEventListener(id==='pm-search'?'input':'change',()=>{page=1;load();});
$('pm-export').onclick=async()=>{const button=$('pm-export');button.disabled=true;try{let all=[],p=1;while(true){const result=await api.request('GET','/maintenance/plans?'+params(p++,50));all.push(...result.items);if(all.length>=result.total)break;}const blob=new Blob([JSON.stringify(all,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='保养计划授权范围.json';a.click();URL.revokeObjectURL(url);}catch(e){Eam.message(e.message);}finally{button.disabled=false;}};
$('pm-columns').onclick=()=>{const table=$('pm-rows').closest('table');$('pm-column-options').replaceChildren();[...table.querySelectorAll('thead th')].forEach((th,i)=>{if(i===0||i===7)return;const label=document.createElement('label');label.className='d-block my-2';const box=document.createElement('input');box.type='checkbox';box.checked=!th.hidden;box.onchange=()=>{hiddenColumns=box.checked?hiddenColumns.filter(x=>x!==i):[...new Set([...hiddenColumns,i])];EamUiComponents.columnVisibility(table,hiddenColumns);};label.append(box,document.createTextNode(' '+th.textContent));$('pm-column-options').append(label);});$('pm-columns-dialog').showModal();};$('pm-column-close').onclick=()=>$('pm-columns-dialog').close();
try{config=await api.request('GET','/maintenance/config');for(const e of config.equipment)$('pm-equipment').add(new Option(e.name,e.id));$('pm-equipment').value=selectedEquipment;if(selectedEquipment)$('pm-equipment').disabled=true;await load();}catch(e){$('pm-load').textContent=e.message;EamUiComponents.setTableStatus('pm-rows','error',e.message,()=>location.reload());}})();

});
